-- ============================================================
-- Import batch KELIMA: 5 Sprin baru (14-17 September 2026) dari
-- C:\Database SPRIN SIandi\PART 4\ -- 4 KRYD harian + 1 Latihan Olah
-- Strategi Aman Nusa II (Penanganan Bencana, jenis kegiatan baru
-- "OPERASI KONTINJENSI" -- sudah dibuat terpisah sebelum skrip ini).
-- 179 baris penempatan personel, semua NRP tervalidasi 100% cocok roster
-- pengguna tanpa koreksi.
--
-- PENTING: jalankan SETELAH jenis_kegiatan "OPERASI KONTINJENSI" dibuat
-- (migrasi 20260916000004_jenis_kegiatan_kontinjensi.sql -- sudah dijalankan
-- langsung lewat REST API, tidak perlu dijalankan ulang di sini).
-- Tidak idempoten sepenuhnya (sprin_kelompok/sprin_personel tidak dicek
-- exists dulu) -- JANGAN dijalankan dua kali.
-- ============================================================

alter table public.surat_perintah disable trigger trg_surat_perintah_before_write;

insert into public.surat_perintah (
  nomor_agenda, nomor_lengkap, jenis_kegiatan_id, perihal, pertimbangan, lokasi,
  tanggal_mulai, tanggal_selesai, jam_apel, butir_untuk,
  status, disusun_oleh, disetujui_oleh, disetujui_pada
)
select
  x.nomor_agenda, x.nomor_lengkap, jk.id, x.perihal, x.pertimbangan, x.lokasi,
  x.tanggal_mulai::date, x.tanggal_selesai::date, nullif(x.jam_apel,'')::time,
  case when x.butir_untuk is null then null
    else array(select jsonb_array_elements_text(x.butir_untuk::jsonb)) end,
  'TERBIT'::status_surat_perintah,
  (select id from public.pengguna where nrp = '87121335'),
  (select id from public.pengguna where nrp = '76010326'),
  x.tanggal_mulai::date::timestamptz
from jsonb_to_recordset('[{"kode":"sprin2112","nomor_agenda":2112,"nomor_lengkap":"SPRIN/2112/IX/PAM.1.3.2./2026","jenis_kegiatan_nama":"KEGIATAN RUTIN YANG DITINGKATKAN","perihal":"Kegiatan Rutin yang ditingkatkan / Patroli dan Razia Skala Besar","pertimbangan":"bahwa dalam rangka Kegiatan Rutin yang ditingkatkan di Wilkum Polres Cimahi, maka dipandang perlu mengeluarkan surat perintah.","lokasi":"Wilkum Polres Cimahi","tanggal_mulai":"2026-09-14","tanggal_selesai":"2026-09-14","jam_apel":"21:00","butir_untuk":null},{"kode":"sprin2120","nomor_agenda":2120,"nomor_lengkap":"SPRIN/2120/IX/PAM.1.3.2./2026","jenis_kegiatan_nama":"KEGIATAN RUTIN YANG DITINGKATKAN","perihal":"Kegiatan Rutin yang ditingkatkan / Patroli dan Razia Skala Besar","pertimbangan":"bahwa dalam rangka Kegiatan Rutin yang ditingkatkan di Wilkum Polres Cimahi, maka dipandang perlu mengeluarkan surat perintah.","lokasi":"Wilkum Polres Cimahi","tanggal_mulai":"2026-09-15","tanggal_selesai":"2026-09-15","jam_apel":"21:00","butir_untuk":null},{"kode":"sprin2125","nomor_agenda":2125,"nomor_lengkap":"SPRIN/2125/IX/PAM.1.3.2./2026","jenis_kegiatan_nama":"KEGIATAN RUTIN YANG DITINGKATKAN","perihal":"Kegiatan Rutin yang ditingkatkan / Patroli dan Razia Skala Besar","pertimbangan":"bahwa dalam rangka Kegiatan Rutin yang ditingkatkan di Wilkum Polres Cimahi, maka dipandang perlu mengeluarkan surat perintah.","lokasi":"Wilkum Polres Cimahi","tanggal_mulai":"2026-09-16","tanggal_selesai":"2026-09-16","jam_apel":"21:00","butir_untuk":null},{"kode":"sprin2128","nomor_agenda":2128,"nomor_lengkap":"SPRIN/2128/IX/PAM.1.3.2./2026","jenis_kegiatan_nama":"KEGIATAN RUTIN YANG DITINGKATKAN","perihal":"Kegiatan Rutin yang ditingkatkan / Patroli dan Razia Skala Besar","pertimbangan":"bahwa dalam rangka Kegiatan Rutin yang ditingkatkan di Wilkum Polres Cimahi, maka dipandang perlu mengeluarkan surat perintah.","lokasi":"Wilkum Polres Cimahi","tanggal_mulai":"2026-09-17","tanggal_selesai":"2026-09-17","jam_apel":"21:00","butir_untuk":null},{"kode":"sprin2130","nomor_agenda":2130,"nomor_lengkap":"SPRIN/2130/IX/OPS.2./2026","jenis_kegiatan_nama":"OPERASI KONTINJENSI","perihal":"Latihan Olah Strategi Aman Nusa II dalam Rangka Penanganan Bencana","pertimbangan":"bahwa dalam rangka Kegiatan Latihan Olah Strategi Aman Nusa II Penanganan Bencana, maka dipandang perlu mengeluarkan surat perintah.","lokasi":"Ruangan ICS Polres Cimahi","tanggal_mulai":"2026-09-17","tanggal_selesai":"2026-09-17","jam_apel":"08:00","butir_untuk":"[\"melaksanakan Latihan Olah Strategi Aman Nusa II dalam Rangka Penanganan Bencana dari Stamaops Polri melalui Zoom meeting;\",\"kegiatan dilaksanakan pada hari Kamis tanggal 17 September 2026, Pukul 08.00 WIB di Ruangan ICS Polres Cimahi;\",\"pakaian PDL – II Two Tone/ Menyesuaikan, untuk operator agar membawa Laptop masing-masing;\",\"melaksanakan perintah ini dengan saksama dan penuh rasa tanggung jawab;\",\"melaporkan hasil pelaksanaan tugas kepada Ka / Waka / Kabag Ops Polres Cimahi pada kesempatan pertama.\"]"}]'::jsonb) as x(
  kode text, nomor_agenda int, nomor_lengkap text, jenis_kegiatan_nama text, perihal text,
  pertimbangan text, lokasi text, tanggal_mulai text, tanggal_selesai text, jam_apel text,
  butir_untuk text
)
join public.jenis_kegiatan jk on jk.nama = x.jenis_kegiatan_nama
where not exists (select 1 from public.surat_perintah sp where sp.nomor_lengkap = x.nomor_lengkap);

alter table public.surat_perintah enable trigger trg_surat_perintah_before_write;

insert into public.dasar_hukum_rujukan (surat_perintah_id, perihal, jenis_dokumen)
select sp.id, x.perihal, x.jenis_dokumen
from jsonb_to_recordset('[{"nomor_lengkap":"SPRIN/2112/IX/PAM.1.3.2./2026","perihal":"Perkiraan Intelijen Singkat Sat Intelkam Polres Cimahi Nomor : R/Kirkat-14/VII/2026/Sat Intelkam tanggal 04 September 2026 tentang Kegiatan Rutin Yang Ditingkatkan di Wilayah Hukum Polres Cimahi","jenis_dokumen":"Rujukan"},{"nomor_lengkap":"SPRIN/2120/IX/PAM.1.3.2./2026","perihal":"Perkiraan Intelijen Singkat Sat Intelkam Polres Cimahi Nomor : R/Kirkat-14/VII/2026/Sat Intelkam tanggal 04 September 2026 tentang Kegiatan Rutin Yang Ditingkatkan di Wilayah Hukum Polres Cimahi","jenis_dokumen":"Rujukan"},{"nomor_lengkap":"SPRIN/2125/IX/PAM.1.3.2./2026","perihal":"Perkiraan Intelijen Singkat Sat Intelkam Polres Cimahi Nomor : R/Kirkat-14/VII/2026/Sat Intelkam tanggal 04 September 2026 tentang Kegiatan Rutin Yang Ditingkatkan di Wilayah Hukum Polres Cimahi","jenis_dokumen":"Rujukan"},{"nomor_lengkap":"SPRIN/2128/IX/PAM.1.3.2./2026","perihal":"Perkiraan Intelijen Singkat Sat Intelkam Polres Cimahi Nomor : R/Kirkat-14/VII/2026/Sat Intelkam tanggal 04 September 2026 tentang Kegiatan Rutin Yang Ditingkatkan di Wilayah Hukum Polres Cimahi","jenis_dokumen":"Rujukan"},{"nomor_lengkap":"SPRIN/2130/IX/OPS.2./2026","perihal":"Surat Telegram Kapolda Jabar Nomor : STR/244/IX/OPS.2/2026 tanggal 16 September 2026 tentang Latihan olah Strategi Aman Nusa II","jenis_dokumen":"Rujukan"}]'::jsonb) as x(nomor_lengkap text, perihal text, jenis_dokumen text)
join public.surat_perintah sp on sp.nomor_lengkap = x.nomor_lengkap;


insert into public.sprin_kelompok (surat_perintah_id, jenis_kegiatan_kelompok_id, nama_kelompok, kelompok_besar, sifat, urutan)
