"nama_kelompok":"SATGAS 6 BAN OPS"},{"nrp_aktif":"95060521","nomor_urut_keseluruhan":27,"nomor_urut_kelompok":4,"jabatan_operasional":"SATGAS 6 BAN OPS","nomor_lengkap":"SPRIN/2130/IX/OPS.2./2026","kelompok_besar":null,"nama_kelompok":"SATGAS 6 BAN OPS"},{"nrp_aktif":"02101044","nomor_urut_keseluruhan":28,"nomor_urut_kelompok":5,"jabatan_operasional":"SATGAS 6 BAN OPS","nomor_lengkap":"SPRIN/2130/IX/OPS.2./2026","kelompok_besar":null,"nama_kelompok":"SATGAS 6 BAN OPS"}]'::jsonb) as x(
  nrp_aktif text, nomor_urut_keseluruhan int, nomor_urut_kelompok int, jabatan_operasional text,
  nomor_lengkap text, kelompok_besar text, nama_kelompok text
)
join public.surat_perintah sp on sp.nomor_lengkap = x.nomor_lengkap
join public.sprin_kelompok sk
  on sk.surat_perintah_id = sp.id
  and sk.nama_kelompok = x.nama_kelompok
  and coalesce(sk.kelompok_besar,'') = coalesce(x.kelompok_besar,'')
join public.pengguna pg on pg.nrp = x.nrp_aktif;


-- Verifikasi jumlah baris:
select
  (select count(*) from public.surat_perintah where nomor_lengkap in ('SPRIN/2112/IX/PAM.1.3.2./2026','SPRIN/2120/IX/PAM.1.3.2./2026','SPRIN/2125/IX/PAM.1.3.2./2026','SPRIN/2128/IX/PAM.1.3.2./2026','SPRIN/2130/IX/OPS.2./2026')) as sprin_masuk,
  (select count(*) from public.sprin_kelompok sk join public.surat_perintah sp on sp.id=sk.surat_perintah_id where sp.nomor_lengkap in ('SPRIN/2112/IX/PAM.1.3.2./2026','SPRIN/2120/IX/PAM.1.3.2./2026','SPRIN/2125/IX/PAM.1.3.2./2026','SPRIN/2128/IX/PAM.1.3.2./2026','SPRIN/2130/IX/OPS.2./2026')) as kelompok_masuk,
  (select count(*) from public.sprin_personel spr join public.sprin_kelompok sk on sk.id=spr.sprin_kelompok_id join public.surat_perintah sp on sp.id=sk.surat_perintah_id where sp.nomor_lengkap in ('SPRIN/2112/IX/PAM.1.3.2./2026','SPRIN/2120/IX/PAM.1.3.2./2026','SPRIN/2125/IX/PAM.1.3.2./2026','SPRIN/2128/IX/PAM.1.3.2./2026','SPRIN/2130/IX/OPS.2./2026')) as personel_masuk;
